// Parse the AI response and extract opportunities
const response = $input.first().json;

// Get the content from the AI response
let content = response.choices[0].message.content;

// Try to parse as JSON, handling potential markdown code blocks
if (content.startsWith('```')) {
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '');
}

try {
  const parsed = JSON.parse(content.trim());

  // Validate we have opportunities array
  if (!parsed.opportunities || !Array.isArray(parsed.opportunities)) {
    throw new Error('Invalid response structure: missing opportunities array');
  }

  // Ensure we have 4-8 opportunities
  const opportunities = parsed.opportunities.slice(0, 8);

  if (opportunities.length < 4) {
    console.warn(`Only ${opportunities.length} opportunities found, minimum is 4`);
  }

  return {
    json: {
      opportunities: opportunities,
      total: opportunities.length,
      original_content: $('Upload Blog Post').first().json['Blog Post (Markdown)'].data
    }
  };
} catch (error) {
  throw new Error(`Failed to parse AI response: ${error.message}. Content: ${content.substring(0, 500)}`);
}

// Split opportunities into individual items for parallel sub-workflow execution
const data = $input.first().json;
const opportunities = data.opportunities;

return opportunities.map((opp, index) => ({
  json: {
    opportunity: opp,
    index: index + 1,
    total: data.total
  }
}));

// Create final summary report
const allResults = $input.first().json.data;

const successful = allResults.filter(r => r.success);
const failed = allResults.filter(r => !r.success);

// Calculate average processing time
const avgChecks = successful.length > 0 
  ? Math.round(successful.reduce((sum, s) => sum + (s.checks_required || 1), 0) / successful.length)
  : 0;

const summary = {
  total_opportunities: allResults.length,
  successful_generations: successful.length,
  failed_generations: failed.length,
  success_rate: Math.round((successful.length / allResults.length) * 100) + '%',
  processing_mode: 'parallel',
  avg_status_checks: avgChecks,
  generated_visuals: successful.map(s => ({
    opportunity_id: s.opportunity_id,
    visual_type: s.visual_type,
    filename: s.filename,
    drive_url: s.drive_url,
    quote: s.original_quote?.substring(0, 100) + '...'
  })),
  failed_visuals: failed.map(f => ({
    opportunity_id: f.opportunity_id,
    visual_type: f.visual_type,
    error: f.error,
    quote: f.original_quote?.substring(0, 100) + '...'
  })),
  timestamp: new Date().toISOString()
};

return { json: summary };
